import 'package:flutter/material.dart';
import '../services/api.dart';
import '../widgets/avatar.dart';
import 'chat_screen.dart';
import 'call_screen.dart';
class UserProfileScreen extends StatefulWidget{final Map<String,dynamic> user;const UserProfileScreen({super.key,required this.user});@override State<UserProfileScreen>createState()=>_UserProfileScreenState();}
class _UserProfileScreenState extends State<UserProfileScreen>{late Map<String,dynamic> user;bool following=false;@override void initState(){super.initState();user=widget.user;load();}Future<void>load()async{try{final j=await Api.request('/user/${user['id']}');if(mounted)setState((){user=Map<String,dynamic>.from(j['user']);following=j['is_following']==true;});}catch(_){}}Future<void>toggle()async{await Api.request(following?'/unfollow':'/follow',method:'POST',body:{'user_id':user['id']});setState(()=>following=!following);}Future<void>chat()async{final j=await Api.request('/conversation/create',method:'POST',body:{'user_id':user['id']});if(mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatScreen(conversationId:int.parse(j['conversation_id'].toString()),other:user)));}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(),body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(children:[Avatar(url:user['avatar'],radius:58),const SizedBox(height:12),Text(user['name']??'',style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:6),Text(user['bio']??''),const SizedBox(height:24),Wrap(spacing:10,children:[FilledButton(onPressed:toggle,child:Text(following?'إلغاء المتابعة':'متابعة')),OutlinedButton(onPressed:chat,child:const Text('رسالة')),IconButton.filledTonal(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>CallScreen(other:user))),icon:const Icon(Icons.videocam))])]))));}
